-- Run in Supabase SQL Editor. Additive: creates only Team Tong namespaced objects.
-- Existing auth.users and other application schemas are never replaced.
BEGIN;
CREATE SCHEMA IF NOT EXISTS team_tong;
REVOKE ALL ON SCHEMA team_tong FROM PUBLIC, anon, authenticated;
CREATE TABLE IF NOT EXISTS team_tong.accounts(id text PRIMARY KEY,email text UNIQUE NOT NULL,name text NOT NULL,password text NOT NULL,role text NOT NULL DEFAULT 'member',status text NOT NULL DEFAULT 'pending',email_verified integer NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS team_tong.sessions(token text PRIMARY KEY,account_id text NOT NULL REFERENCES team_tong.accounts(id),expires bigint NOT NULL);
CREATE TABLE IF NOT EXISTS team_tong.presence(session text NOT NULL,match_id text NOT NULL,seen bigint NOT NULL,PRIMARY KEY(session,match_id));
CREATE TABLE IF NOT EXISTS team_tong.club(id integer PRIMARY KEY CHECK(id=1),payload text NOT NULL);
CREATE TABLE IF NOT EXISTS team_tong.audit(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,actor text NOT NULL,action text NOT NULL,created bigint NOT NULL);
CREATE TABLE IF NOT EXISTS team_tong.attempts(key text PRIMARY KEY,count integer NOT NULL,until bigint NOT NULL);
CREATE TABLE IF NOT EXISTS team_tong.rooms(id text PRIMARY KEY,name text NOT NULL,logo text,code text NOT NULL UNIQUE,owner text REFERENCES team_tong.accounts(id),archived integer NOT NULL DEFAULT 0,payload text NOT NULL,created bigint NOT NULL);
CREATE TABLE IF NOT EXISTS team_tong.room_memberships(room_id text REFERENCES team_tong.rooms(id),account_id text REFERENCES team_tong.accounts(id),role text NOT NULL CHECK(role IN ('owner','organizer','member')),status text NOT NULL CHECK(status IN ('pending','approved','rejected')),PRIMARY KEY(room_id,account_id));
CREATE TABLE IF NOT EXISTS team_tong.room_transfers(room_id text PRIMARY KEY REFERENCES team_tong.rooms(id),target text NOT NULL REFERENCES team_tong.accounts(id),requested_by text NOT NULL REFERENCES team_tong.accounts(id));
CREATE TABLE IF NOT EXISTS team_tong.room_audit(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,room_id text NOT NULL REFERENCES team_tong.rooms(id),actor text NOT NULL,action text NOT NULL,created bigint NOT NULL);
CREATE TABLE IF NOT EXISTS team_tong.email_tokens(token text PRIMARY KEY,account_id text REFERENCES team_tong.accounts(id),kind text NOT NULL,expires bigint NOT NULL);
CREATE TABLE IF NOT EXISTS team_tong.room_presence(room_id text NOT NULL REFERENCES team_tong.rooms(id),session text NOT NULL,match_id text NOT NULL,seen bigint NOT NULL,PRIMARY KEY(room_id,session,match_id));
CREATE TABLE IF NOT EXISTS team_tong.profiles(account_id text PRIMARY KEY REFERENCES team_tong.accounts(id),username text NOT NULL,position text NOT NULL,number integer NOT NULL,portrait text);
CREATE TABLE IF NOT EXISTS team_tong.room_creation_requests(account_id text REFERENCES team_tong.accounts(id),request_id text NOT NULL,room_id text NOT NULL REFERENCES team_tong.rooms(id),PRIMARY KEY(account_id,request_id));
CREATE TABLE IF NOT EXISTS team_tong.guest_sessions(token text PRIMARY KEY,room_id text NOT NULL REFERENCES team_tong.rooms(id),code_hash text NOT NULL,expires bigint NOT NULL);
CREATE TABLE IF NOT EXISTS team_tong.auth_links(auth_id uuid PRIMARY KEY REFERENCES auth.users(id),account_id text UNIQUE NOT NULL REFERENCES team_tong.accounts(id));
CREATE TABLE IF NOT EXISTS team_tong.auth_session_revocations(token text PRIMARY KEY,expires bigint NOT NULL);
CREATE TABLE IF NOT EXISTS team_tong.imports(source_hash text PRIMARY KEY,created timestamptz NOT NULL DEFAULT now(),manifest jsonb NOT NULL);
CREATE TABLE IF NOT EXISTS team_tong.migrations(version integer PRIMARY KEY);
INSERT INTO team_tong.migrations VALUES(1) ON CONFLICT DO NOTHING;
-- No browser role can read private accounts, room payloads, ballots or guest tokens.
DO $$ DECLARE t record; BEGIN FOR t IN SELECT tablename FROM pg_tables WHERE schemaname='team_tong' LOOP
 EXECUTE format('ALTER TABLE team_tong.%I ENABLE ROW LEVEL SECURITY',t.tablename);
 EXECUTE format('REVOKE ALL ON team_tong.%I FROM PUBLIC, anon, authenticated',t.tablename);
END LOOP; END $$;
-- Realtime emits only a changing revision, never the room payload or individual votes.
CREATE TABLE IF NOT EXISTS public.team_tong_room_activity(room_id text PRIMARY KEY REFERENCES team_tong.rooms(id),revision bigint NOT NULL DEFAULT 0);
ALTER TABLE public.team_tong_room_activity ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.team_tong_room_activity FROM PUBLIC, anon, authenticated;
GRANT SELECT ON public.team_tong_room_activity TO authenticated;
CREATE OR REPLACE FUNCTION public.team_tong_can_view_room(room text) RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$
 SELECT EXISTS(SELECT 1 FROM team_tong.auth_links l JOIN team_tong.accounts a ON a.id=l.account_id JOIN team_tong.room_memberships m ON m.account_id=a.id JOIN team_tong.rooms r ON r.id=m.room_id WHERE l.auth_id=auth.uid() AND m.room_id=room AND m.status='approved' AND a.status!='suspended' AND r.archived=0)
$$;
REVOKE ALL ON FUNCTION public.team_tong_can_view_room(text) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.team_tong_can_view_room(text) TO authenticated;
DROP POLICY IF EXISTS team_tong_room_member ON public.team_tong_room_activity;
CREATE POLICY team_tong_room_member ON public.team_tong_room_activity FOR SELECT TO authenticated USING(public.team_tong_can_view_room(room_id));
CREATE OR REPLACE FUNCTION team_tong.notify_room() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ BEGIN
 INSERT INTO public.team_tong_room_activity(room_id,revision) VALUES(NEW.id,1) ON CONFLICT(room_id) DO UPDATE SET revision=public.team_tong_room_activity.revision+1;
 RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS team_tong_room_changed ON team_tong.rooms;
CREATE TRIGGER team_tong_room_changed AFTER INSERT OR UPDATE ON team_tong.rooms FOR EACH ROW EXECUTE FUNCTION team_tong.notify_room();
DO $$ BEGIN IF EXISTS(SELECT 1 FROM pg_publication WHERE pubname='supabase_realtime') AND NOT EXISTS(SELECT 1 FROM pg_publication_tables WHERE pubname='supabase_realtime' AND schemaname='public' AND tablename='team_tong_room_activity') THEN ALTER PUBLICATION supabase_realtime ADD TABLE public.team_tong_room_activity; END IF; END $$;
COMMIT;
